package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import dustin.cex.domains.bitcoin.*;
import dustin.cex.domains.auth.model.entity.UserRole;
import dustin.cex.domains.security.OperatorMfaService;
import dustin.cex.shared.http.EngineDepositClient;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.transaction.support.*;

/** 실제 적립/원장과 두 대사를 준비한 뒤 실제 보안키의 독립 승인으로 정확한 위험 구간만 해제한다. */
class BitcoinChainClearanceIntegrationTest extends BitcoinCreditTestSupport {
    @Autowired BitcoinChainRecoveryProofs proofs;
    @Autowired BitcoinChainRecoveryClearances clearances;
    @Autowired BitcoinCreditDispatches dispatch;
    @Autowired BitcoinObservationService observations;
    @Autowired dustin.cex.shared.kafka.KafkaOrderEventConsumer consumer;
    @MockitoBean dustin.cex.domains.reconciliation.EngineAuditClient engineSource;
    BitcoinChainRecoveryProofs.Report recovery;
    @BeforeEach void recovered(){
        credits.reserve(receipt.id());when(depositEngine.credit(any())).thenReturn(EngineDepositClient.Outcome.DURABLY_CREDITED);dispatch.execute(receipt.id()).orElseThrow();
        UUID engineId=UUID.randomUUID();String raw=json.writeValueAsString(Map.of("event_id",engineId+":1:0","engine_id",engineId,"event_type","deposit_credited","deposit_id",receipt.id(),"user_id",customer.getId(),"asset","BTC","amount","0.12345678","timestamp",Instant.now().toString()));
        new TransactionTemplate(manager).executeWithoutResult(t->consumer.consumeOrderEvent(raw));
        var page=json.createObjectNode();page.put("engine_id",engineId.toString());page.put("through",1);page.put("next_after",1);page.putArray("events").add(raw);when(engineSource.page(anyLong(),any(),any())).thenReturn(page);
        when(node.inspect(receipt.txid())).thenReturn(metadata(BitcoinDepositReader.Status.UNCONFIRMED,0));observations.refresh(receipt.txid());
        when(node.inspect(receipt.txid())).thenReturn(metadata(BitcoinDepositReader.Status.CONFIRMED,6));
        recovery=proofs.prepare(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID());assertEquals("READY",recovery.state());assertFalse(eligible());
        clearInvocations(depositEngine,node,engineSource);
    }
    BitcoinDepositReader.Observation metadata(BitcoinDepositReader.Status status,long confirmations){return new BitcoinDepositReader.Observation("bitcoin-regtest",receipt.txid(),status,confirmations,false,false,status==BitcoinDepositReader.Status.CONFIRMED?"a".repeat(64):null,status==BitcoinDepositReader.Status.CONFIRMED?0L:null,"b".repeat(64),status==BitcoinDepositReader.Status.CONFIRMED?confirmations-1:5,List.of(new BitcoinDepositReader.Output(0,receipt.address(),receipt.script(),new BigDecimal("0.12345678"))));}
    BitcoinChainRecoveryClearances.Request request(){return clearances.propose(maker.user().getId(),maker.sid(),recovery.id(),checker.user().getId(),UUID.randomUUID());}
    boolean eligible(){return new TransactionTemplate(manager).execute(t->eligibility.permitted(users.lockById(customer.getId()).orElseThrow()));}
    long rows(String table){return jdbc.queryForObject("SELECT count(*) FROM "+table,Long.class);}
    OperatorMfaService.AuthorizationProof signature(BitcoinChainRecoveryClearances.Request r,boolean approve)throws Exception{
        var options=clearances.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),approve).authentication();
        return new OperatorMfaService.AuthorizationProof(options.challengeId(),checker.key().assertion(options,"http://localhost:3003",true,counter.incrementAndGet(),null));
    }
    BitcoinChainRecoveryClearances.Request decide(BitcoinChainRecoveryClearances.Request r,boolean approve)throws Exception{
        clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());return clearances.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),approve,signature(r,approve));
    }
    @Override @AfterEach void noExternalOrFinancialRelease(){verifyNoInteractions(directoryClient,transactions,transfers,client,engine,producer,priceClient,depositEngine);assertEquals(1,rows("bitcoin_credited_deposits"));}
    @Test void independentContentSignedApprovalClearsOnlyTheKnownRiskWithoutMovingMoney()throws Exception{
        long entries=rows("ledger_entries");var r=request();assertEquals("PENDING",r.status());assertFalse(eligible());assertEquals("0.12345678",r.payload().amount());
        assertEquals("APPROVED",decide(r,true).status());assertTrue(eligible());assertEquals(0,rows("bitcoin_credit_chain_risks"));assertEquals(1,rows("bitcoin_credit_chain_risk_history"));assertEquals(entries,rows("ledger_entries"));
        assertEquals(0,new BigDecimal("0.12345678").compareTo(jdbc.queryForObject("SELECT available FROM user_balances WHERE user_id=? AND mint_address='BTC'",BigDecimal.class,customer.getId())));verifyNoInteractions(node,engineSource);
    }
    @Test void rejectionPreservesTheRiskAndCannotBeApprovedAgain()throws Exception{var r=request();assertEquals("REJECTED",decide(r,false).status());assertFalse(eligible());assertEquals(1,rows("bitcoin_credit_chain_risks"));assertEquals(409,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->clearances.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true)).getStatusCode().value());verifyNoInteractions(node,engineSource);}
    @Test void aNewRiskAfterApprovalBlocksAgainAndKeepsTheEarlierDecision()throws Exception{var r=request();decide(r,true);assertTrue(eligible());when(node.inspect(receipt.txid())).thenReturn(metadata(BitcoinDepositReader.Status.UNCONFIRMED,0));observations.refresh(receipt.txid());assertFalse(eligible());assertEquals(1,rows("bitcoin_credit_chain_risks"));assertEquals(2,rows("bitcoin_credit_chain_risk_history"));assertEquals(1,rows("bitcoin_chain_clearance_decisions"));}
    void denied(int status,org.junit.jupiter.api.function.Executable work){assertEquals(status,assertThrows(org.springframework.web.server.ResponseStatusException.class,work).getStatusCode().value());}
    @Test void theCheckerMustActuallyInspectTheExactRequestBeforeSigning(){var r=request();denied(409,()->clearances.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));assertEquals(0,rows("bitcoin_chain_clearance_decisions"));}
    @Test void aDifferentPayloadHashCannotBorrowTheSameRequest(){var r=request();clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());denied(409,()->clearances.options(checker.user().getId(),checker.sid(),r.payload().id(),"c".repeat(64),true));assertFalse(eligible());}
    @Test void aRejectionSignatureCannotBeUsedAsApproval()throws Exception{var r=request();clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());var proof=signature(r,false);denied(403,()->clearances.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true,proof));assertEquals(0,rows("bitcoin_chain_clearance_decisions"));assertFalse(eligible());}
    @Test void aMissingSignatureCannotClearTheRisk(){var r=request();clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());denied(403,()->clearances.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true,null));assertFalse(eligible());}
    @Test void requestAuditFailureRollsBackTheRequestAndItsMfaBinding(){doThrow(new IllegalStateException("격리 해제 요청 감사 실패")).when(audit).record(anyLong(),eq("BTC_CHAIN_CLEARANCE_PROPOSED"),anyString(),anyString(),anyString());long bindings=rows("operator_approval_bindings");assertThrows(RuntimeException.class,()->request());assertEquals(0,rows("bitcoin_chain_clearance_requests"));assertEquals(bindings,rows("operator_approval_bindings"));assertFalse(eligible());}
    @Test void silentlyOmittedRequestAuditCannotCommit(){doNothing().when(audit).record(anyLong(),eq("BTC_CHAIN_CLEARANCE_PROPOSED"),anyString(),anyString(),anyString());assertThrows(org.springframework.dao.DataAccessException.class,()->request());assertEquals(0,rows("bitcoin_chain_clearance_requests"));}
    @Test void viewAuditFailureCannotLeaveAnInspectionReceipt(){var r=request();doThrow(new IllegalStateException("격리 해제 열람 감사 실패")).when(audit).record(anyLong(),eq("BTC_CHAIN_CLEARANCE_VIEWED"),anyString(),anyString(),anyString());assertThrows(RuntimeException.class,()->clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id()));assertEquals(0,rows("bitcoin_chain_clearance_views"));denied(409,()->clearances.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));}
    @Test void silentlyOmittedViewAuditCannotCommit(){var r=request();doNothing().when(audit).record(anyLong(),eq("BTC_CHAIN_CLEARANCE_VIEWED"),anyString(),anyString(),anyString());assertThrows(org.springframework.dao.DataAccessException.class,()->clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id()));assertEquals(0,rows("bitcoin_chain_clearance_views"));}
    @Test void decisionAuditFailureRollsBackBothClearanceAndSignatureConsumption()throws Exception{
        var r=request();clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());var proof=signature(r,true);
        doThrow(new IllegalStateException("격리 해제 결정 감사 실패")).when(audit).record(anyLong(),eq("BTC_CHAIN_CLEARANCE_DECIDED"),anyString(),anyString(),anyString());
        assertThrows(RuntimeException.class,()->clearances.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true,proof));assertEquals(0,rows("bitcoin_chain_clearance_decisions"));assertFalse(eligible());
        assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,proof.challengeId()));
        doCallRealMethod().when(audit).record(anyLong(),eq("BTC_CHAIN_CLEARANCE_DECIDED"),anyString(),anyString(),anyString());assertEquals("APPROVED",clearances.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true,proof).status());assertTrue(eligible());
    }
    @Test void silentlyOmittedDecisionAuditCannotCommitAnActiveClearance()throws Exception{var r=request();clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());var proof=signature(r,true);doNothing().when(audit).record(anyLong(),eq("BTC_CHAIN_CLEARANCE_DECIDED"),anyString(),anyString(),anyString());assertThrows(org.springframework.dao.DataAccessException.class,()->clearances.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true,proof));assertEquals(0,rows("bitcoin_chain_clearance_decisions"));assertFalse(eligible());assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,proof.challengeId()));}
    @Test void aNewRiskBeforeTheDecisionInvalidatesTheSignedOldScope()throws Exception{var r=request();clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());var proof=signature(r,true);when(node.inspect(receipt.txid())).thenReturn(metadata(BitcoinDepositReader.Status.UNCONFIRMED,0));observations.refresh(receipt.txid());denied(409,()->clearances.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true,proof));assertEquals(2,rows("bitcoin_credit_chain_risks"));assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,proof.challengeId()));}
    @Test void healthyPollingWithTheSameAnchorDoesNotInvalidateTheRiskScope()throws Exception{var r=request();var observed=observations.refresh(receipt.txid());new TransactionTemplate(manager).executeWithoutResult(t->qualification.evaluate(observed.id()));assertEquals("APPROVED",decide(r,true).status());assertTrue(eligible());}
    @Test void aLaterFailedNativeReconciliationInvalidatesTheEarlierReadyProof(){var r=request();when(node.inspect(receipt.txid())).thenThrow(new IllegalStateException("격리 노드 장애"));assertEquals(BitcoinDepositReconciliationService.Status.FAILED,reconciliation.reconcile(receipt.id()).status());clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());denied(409,()->clearances.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));assertFalse(eligible());}
    @Test void aChangedFinancialProjectionCannotUseTheOldRecoveryProof(){var r=request();jdbc.update("UPDATE user_balances SET available=available+1 WHERE user_id=? AND mint_address='BTC'",customer.getId());clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());denied(409,()->clearances.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));assertEquals(0,rows("bitcoin_chain_clearance_decisions"));assertEquals(0,new BigDecimal("1.12345678").compareTo(jdbc.queryForObject("SELECT available FROM user_balances WHERE user_id=? AND mint_address='BTC'",BigDecimal.class,customer.getId())));}
    @Test void disablingTheRequesterInvalidatesTheAssignedApproval(){var r=request();var user=users.findById(maker.user().getId()).orElseThrow();user.setEnabled(false);users.saveAndFlush(user);denied(403,()->clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id()));assertFalse(eligible());}
    @Test void disablingTheCheckerInvalidatesTheAssignedApproval(){var r=request();var user=users.findById(checker.user().getId()).orElseThrow();user.setEnabled(false);users.saveAndFlush(user);denied(403,()->clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id()));assertFalse(eligible());}
    @Test void clearingTheChainRiskDoesNotEnableADisabledCustomer()throws Exception{var r=request();var user=users.findById(customer.getId()).orElseThrow();user.setEnabled(false);users.saveAndFlush(user);assertEquals("APPROVED",decide(r,true).status());assertFalse(users.findById(customer.getId()).orElseThrow().isEnabled());assertFalse(eligible());assertEquals(0,rows("bitcoin_credit_chain_risks"));}
    @Test void clearingTheChainRiskDoesNotRemoveAnotherTradingRestriction()throws Exception{var r=request();var user=users.findById(customer.getId()).orElseThrow();user.setTradingRestricted(true);users.saveAndFlush(user);assertEquals("APPROVED",decide(r,true).status());assertTrue(users.findById(customer.getId()).orElseThrow().isTradingRestricted());assertFalse(eligible());}
    @Test void sameKeyHasOneRequestAndCannotAssignAnotherChecker()throws Exception{UUID key=UUID.randomUUID();var first=clearances.propose(maker.user().getId(),maker.sid(),recovery.id(),checker.user().getId(),key);assertEquals(first,clearances.propose(maker.user().getId(),maker.sid(),recovery.id(),checker.user().getId(),key));var other=account(UserRole.APPROVER);denied(409,()->clearances.propose(maker.user().getId(),maker.sid(),recovery.id(),other.user().getId(),key));assertEquals(1,rows("bitcoin_chain_clearance_requests"));verifyNoInteractions(node,engineSource);}
    @Test void theSamePersonCannotActAsTwoDifferentAccounts(){var user=users.findById(checker.user().getId()).orElseThrow();user.setOperatorPersonId(maker.user().getOperatorPersonId());users.saveAndFlush(user);denied(403,()->request());assertEquals(0,rows("bitcoin_chain_clearance_requests"));}
    @Test void customerAndAuditorCannotProposeOrInspectAnAssignedClearance()throws Exception{var r=request();denied(403,()->clearances.propose(customer.getId(),sid,recovery.id(),checker.user().getId(),UUID.randomUUID()));var auditor=account(UserRole.AUDITOR);denied(403,()->clearances.inspect(auditor.user().getId(),auditor.sid(),r.payload().id()));denied(403,()->clearances.inspect(customer.getId(),sid,r.payload().id()));denied(403,()->clearances.inspect(checker.user().getId(),maker.sid(),r.payload().id()));assertFalse(eligible());}
    @Test void anUnassignedOperatorCannotBorrowAnotherOperatorsRecoveryProof()throws Exception{var other=account(UserRole.OPERATOR);denied(403,()->clearances.propose(other.user().getId(),other.sid(),recovery.id(),checker.user().getId(),UUID.randomUUID()));assertEquals(0,rows("bitcoin_chain_clearance_requests"));}
    @Test void immutableRequestsInspectionsAndDecisionsCannotBeEdited()throws Exception{var r=request();decide(r,true);for(String table:List.of("bitcoin_chain_clearance_requests","bitcoin_chain_clearance_views","bitcoin_chain_clearance_decisions"))for(String sql:List.of("DELETE FROM "+table,"TRUNCATE "+table+" CASCADE","UPDATE "+table+" SET created_txid=created_txid"))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(sql));assertTrue(eligible());assertEquals(1,rows("bitcoin_credit_chain_risk_history"));}
    @Test void parallelDecisionsConsumeOneSignatureAndClearOnce()throws Exception{
        var r=request();clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());var proof=signature(r,true);var ready=new java.util.concurrent.CountDownLatch(2);var go=new java.util.concurrent.CountDownLatch(1);
        try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){
            java.util.concurrent.Callable<String> call=()->{ready.countDown();assertTrue(go.await(5,java.util.concurrent.TimeUnit.SECONDS));try{return clearances.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true,proof).status();}catch(org.springframework.web.server.ResponseStatusException duplicate){return Integer.toString(duplicate.getStatusCode().value());}};
            var a=pool.submit(call);var b=pool.submit(call);assertTrue(ready.await(5,java.util.concurrent.TimeUnit.SECONDS));go.countDown();assertEquals(Set.of("APPROVED","409"),Set.of(a.get(10,java.util.concurrent.TimeUnit.SECONDS),b.get(10,java.util.concurrent.TimeUnit.SECONDS)));
        }assertEquals(1,rows("bitcoin_chain_clearance_decisions"));assertTrue(eligible());
    }
    @Test void directSqlCannotClearWithoutAConsumedMatchingAuthorization(){var r=request();clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());assertThrows(org.springframework.dao.DataAccessException.class,()->new TransactionTemplate(manager).executeWithoutResult(t->{jdbc.update("INSERT INTO bitcoin_chain_clearance_decisions(request_id,approver_id,session_id,approved,payload_hash,authorization_id) VALUES(?,?,?,?,?,?)",r.payload().id(),checker.user().getId(),checker.sid(),true,r.payloadHash(),UUID.randomUUID());audit.record(checker.user().getId(),"BTC_CHAIN_CLEARANCE_DECIDED","bitcoin-chain-clearance:"+r.payload().id(),"SUCCESS",r.payloadHash());}));assertEquals(0,rows("bitcoin_chain_clearance_decisions"));assertFalse(eligible());}
    @Test void ambientTransactionsAndNilKeysCannotCreateClearanceRequests(){assertThrows(IllegalStateException.class,()->new TransactionTemplate(manager).execute(t->request()));denied(400,()->clearances.propose(maker.user().getId(),maker.sid(),recovery.id(),checker.user().getId(),new UUID(0,0)));assertEquals(0,rows("bitcoin_chain_clearance_requests"));}
    @Test void actualHttpEnforcesRoleBoundariesAndShowsTheExactSignedTerms()throws Exception{
        String uri="/api/admin/deposits/BTC/chain-clearances",body=json.writeValueAsString(Map.of("proofId",recovery.id(),"checkerId",checker.user().getId()));
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(uri).header("Idempotency-Key",UUID.randomUUID()).contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(uri).header("Idempotency-Key",UUID.randomUUID()).header("Authorization","Bearer "+checker.access()).contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isForbidden());
        var raw=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(uri).header("Idempotency-Key",UUID.randomUUID()).header("Authorization","Bearer "+maker.access()).contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andReturn().getResponse().getContentAsString();
        var r=json.readValue(raw,BitcoinChainRecoveryClearances.Request.class);assertEquals("0.12345678",r.payload().amount());assertEquals(recovery.scopeHash(),r.payload().scopeHash());
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(uri+"/"+r.payload().id()).header("Authorization","Bearer "+checker.access())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store")));assertFalse(eligible());
    }
    @Test void aNewObservationWithoutItsCurrentQualificationCannotReuseTheOldDecision(){var r=request();observations.refresh(receipt.txid());clearances.inspect(checker.user().getId(),checker.sid(),r.payload().id());denied(409,()->clearances.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));assertFalse(eligible());}
    @Test void anUnknownSourceDoesNotRevealItsExistenceBeforeCurrentAuthorization(){denied(403,()->clearances.propose(customer.getId(),sid,UUID.randomUUID(),checker.user().getId(),UUID.randomUUID()));denied(403,()->clearances.inspect(customer.getId(),sid,UUID.randomUUID()));denied(404,()->clearances.inspect(checker.user().getId(),checker.sid(),UUID.randomUUID()));}
}
